// 📊 COLLECTEUR - Préserve TOUTES les données webhook
const webhookData = $input.item;

console.log('📊 WEBHOOK DONNÉES REÇUES:');
console.log('- JSON présent:', !!webhookData.json);
console.log('- JSON keys:', webhookData.json ? Object.keys(webhookData.json) : 'null');
console.log('- Binary présent:', !!webhookData.binary);
console.log('- Binary keys:', webhookData.binary ? Object.keys(webhookData.binary) : 'null');
console.log('- Contenu:', webhookData.json?.body?.contenu?.substring(0, 100));

// Préserver EXACTEMENT les données webhook
const result = {
  json: {
    webhook_original: webhookData.json,
    contenu_original: webhookData.json?.body?.contenu || 'Pas de contenu détecté',
    subtitle_original: webhookData.json?.body?.subtitle || '',
    timestamp: new Date().toISOString(),
    collecteur_status: 'données_preservées'
  },
  binary: webhookData.binary || {}
};

console.log('✅ COLLECTEUR - DONNÉES SAUVÉES:');
console.log('- Contenu length:', result.json.contenu_original.length);
console.log('- Binary keys:', Object.keys(result.binary));
console.log('- Binary count:', Object.keys(result.binary).length);

return result;

// 🔗 FUSION FINALE - Combine collector + OpenAI
// FIX: Utiliser $input.all() pour récupérer les données

const allInputs = $input.all();
console.log('🔗 FUSION - INPUTS REÇUS:', allInputs.length);

// Identifier les inputs par leur contenu
let collectorData = null;
let openAIData = null;

allInputs.forEach((input, index) => {
  console.log(`Input ${index}:`, {
    hasJson: !!input.json,
    hasBinary: !!input.binary,
    jsonKeys: input.json ? Object.keys(input.json) : [],
    isCollector: !!(input.json?.collecteur_status),
    isOpenAI: Array.isArray(input.json)
  });

  // Détecter le collecteur
  if (input.json?.collecteur_status) {
    collectorData = input;
    console.log('✅ COLLECTEUR IDENTIFIÉ');
  }

  // Détecter OpenAI (structure array avec message)
  if (Array.isArray(input.json) && input.json[0]?.message) {
    openAIData = input;
    console.log('✅ OPENAI IDENTIFIÉ');
  }
});

// Parse des données IA
let aiTitle = 'Titre par défaut';
let aiSubtitle = 'Sous-titre par défaut';
let aiBody = collectorData?.json?.contenu_original || 'Corps par défaut';

if (openAIData?.json && Array.isArray(openAIData.json)) {
  const aiMessage = openAIData.json[0]?.message;
  if (aiMessage?.content) {
    console.log('🤖 AI CONTENT BRUT:', aiMessage.content.substring(0, 200));

    try {
      const cleanJson = aiMessage.content
        .replace(/```json/g, '')
        .replace(/```/g, '')
        .trim();

      const parsed = JSON.parse(cleanJson);
      console.log('🤖 AI PARSÉ:', parsed);

      aiTitle = parsed.title || aiTitle;
      aiSubtitle = parsed.subtitle || aiSubtitle;
      aiBody = parsed.body || aiBody;

      console.log('✅ IA PARSING RÉUSSI');
    } catch (error) {
      console.log('❌ IA PARSING ÉCHOUÉ:', error.message);
    }
  }
}

// Fusionner toutes les données
const result = {
  json: {
    // Données originales
    contenu_original: collectorData?.json?.contenu_original,
    subtitle_original: collectorData?.json?.subtitle_original,

    // Données IA optimisées
    ai_title: aiTitle,
    ai_subtitle: aiSubtitle,
    ai_body: aiBody,

    // Debug détaillé
    debug: {
      inputs_received: allInputs.length,
      collector_found: !!collectorData,
      openai_found: !!openAIData,
      ai_parsed_success: aiTitle !== 'Titre par défaut',
      binary_preserved: !!(collectorData?.binary && Object.keys(collectorData.binary).length > 0),
      binary_count: collectorData?.binary ? Object.keys(collectorData.binary).length : 0
    }
  },
  binary: collectorData?.binary || {}
};

console.log('🎯 FUSION FINALE:');
console.log('- AI Title:', result.json.ai_title);
console.log('- AI Subtitle:', result.json.ai_subtitle);
console.log('- Binary preserved:', result.json.debug.binary_preserved);
console.log('- Binary count:', result.json.debug.binary_count);

return result;

// ✅ RÉSULTAT FINAL OPTIMISÉ
const flaskResult = $input.item.json;
const fusionData = $input.first();

console.log('✅ RÉSULTAT FINAL:');
console.log('- Flask success:', !!flaskResult?.success);
console.log('- Project ID:', flaskResult?.project_id);
console.log('- Fusion debug:', fusionData?.json?.debug);

if (flaskResult?.success) {
  return {
    json: {
      status: 'success',
      project_id: flaskResult.project_id,
      download_url: `http://host.docker.internal:5003/api/download/${flaskResult.project_id}`,
      message: '🎉 Document InDesign créé avec IA + images !',

      ai_analysis: {
        title: fusionData?.json?.ai_title || 'Titre non disponible',
        subtitle: fusionData?.json?.ai_subtitle || 'Sous-titre non disponible',
        body_preview: (fusionData?.json?.ai_body || 'Corps non disponible').substring(0, 100) + '...'
      },

      technical_details: {
        ai_parsing_success: fusionData?.json?.debug?.ai_parsed_success,
        binary_preserved: fusionData?.json?.debug?.binary_preserved,
        binary_count: fusionData?.json?.debug?.binary_count,
        workflow_execution: 'completed'
      }
    }
  };
}

return {
  json: {
    status: 'error',
    error: flaskResult?.error || 'Erreur Flask inconnue',
    flask_response: flaskResult,
    fusion_debug: fusionData?.json?.debug,
    message: '❌ Échec de création du document'
  }
};
